CREATE TRIGGER nc_prepaid_requests_generation_update AFTER update ON nc_prepaid_requests BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_prepaid_requests_generation_delete AFTER delete ON nc_prepaid_requests BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
