CREATE TRIGGER nc_prepaid_ledger_immutable_delete BEFORE delete ON nc_prepaid_ledger WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_prepaid_requests_content BEFORE UPDATE OF subscription_id,customer_id,kind,payload_json,base_revision,prepared_by_id,prepared_by,prepared_at ON nc_prepaid_requests WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_prepaid_consents_content BEFORE UPDATE OF subscription_id,customer_id,request_id,terms_json,threshold_n,approved_at ON nc_prepaid_consents WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_prepaid_funding_intents_content BEFORE UPDATE OF subscription_id,customer_id,request_id,consent_id,amount_cents,terms_json,created_at ON nc_prepaid_funding_intents WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_prepaid_request_decided BEFORE UPDATE ON nc_prepaid_requests WHEN OLD.status<>'pending' AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_prepaid_funding_decided BEFORE UPDATE ON nc_prepaid_funding_intents WHEN OLD.status<>'pending' AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE UNIQUE INDEX nc_prepaid_draw_once ON nc_prepaid_ledger(grant_id,invoice_id,line_index,service_date) WHERE kind='drawdown';
CREATE UNIQUE INDEX nc_prepaid_grant_once ON nc_prepaid_ledger(grant_id) WHERE kind='grant';
CREATE TRIGGER nc_prepaid_ledger_value BEFORE INSERT ON nc_prepaid_ledger WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND (
 NEW.kind<>'correction' AND COALESCE((SELECT SUM(liability_cents) FROM nc_prepaid_ledger WHERE grant_id=NEW.grant_id),0)+NEW.liability_cents<0
 OR NEW.kind='grant' AND NOT EXISTS(SELECT 1 FROM nc_prepaid_grants WHERE id=NEW.grant_id AND amount_n=NEW.amount_n AND value_cents=NEW.liability_cents AND NEW.recognition_cents=0)
 OR NEW.kind NOT IN ('grant','correction') AND (NEW.amount_n>0 OR NEW.liability_cents>0 OR NEW.recognition_cents<>-NEW.liability_cents)
 OR NEW.kind='correction' AND NEW.recognition_cents<>-NEW.liability_cents
) BEGIN SELECT RAISE(ABORT,'nectar_guard_prepaid_value_changed'); END;
CREATE TABLE nc_prepaid_corrections(id TEXT PRIMARY KEY REFERENCES nc_usage_corrections(id),subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),basis TEXT NOT NULL,applied_at INTEGER NOT NULL);
ALTER TABLE nc_prepaid_ledger ADD COLUMN correction_id TEXT REFERENCES nc_prepaid_corrections(id);
ALTER TABLE nc_prepaid_ledger ADD COLUMN correction_kind TEXT CHECK(correction_kind IN ('drawdown','expiry','rollover'));
CREATE TRIGGER nc_prepaid_correction_source BEFORE INSERT ON nc_prepaid_ledger WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND ((NEW.kind='correction' AND (NEW.correction_kind IS NULL OR NOT EXISTS(SELECT 1 FROM nc_prepaid_corrections c WHERE c.id=NEW.correction_id AND c.subscription_id=NEW.subscription_id AND c.customer_id=NEW.customer_id))) OR (NEW.kind<>'correction' AND (NEW.correction_id IS NOT NULL OR NEW.correction_kind IS NOT NULL))) BEGIN SELECT RAISE(ABORT,'nectar_guard_prepaid_correction_source_changed'); END;
CREATE INDEX nc_prepaid_ledger_correction ON nc_prepaid_ledger(correction_id) WHERE correction_id IS NOT NULL;

CREATE TRIGGER nc_prepaid_corrections_generation_insert AFTER insert ON nc_prepaid_corrections BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_prepaid_corrections_generation_update AFTER update ON nc_prepaid_corrections BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_prepaid_corrections_generation_delete AFTER delete ON nc_prepaid_corrections BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_prepaid_corrections_owned_insert BEFORE insert ON nc_prepaid_corrections WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_customers WHERE id IN (NEW.customer_id) AND erased_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'nectar_guard_customer_erased'); END;
CREATE TRIGGER nc_prepaid_corrections_owned_update BEFORE update ON nc_prepaid_corrections WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_customers WHERE id IN (NEW.customer_id,OLD.customer_id) AND erased_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'nectar_guard_customer_erased'); END;
CREATE TRIGGER nc_prepaid_corrections_immutable_update BEFORE update ON nc_prepaid_corrections WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_prepaid_corrections_immutable_delete BEFORE delete ON nc_prepaid_corrections WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
